import hashlib, json

def ilk_fark(a: bytes, b: bytes) -> int:
    for i, (x, y) in enumerate(zip(a, b)):
        if x != y:
            return i
    return min(len(a), len(b))

def fark_kaydi(adim, eski: bytes, yeni: bytes):
    if eski == yeni:
        return None
    iz = hashlib.sha256(eski + yeni).hexdigest()
    return {"adim": adim,
            "ilk_fark": ilk_fark(eski, yeni),
            "uzunluk": [len(eski), len(yeni)],
            "iz": iz[:12]}

# eski_cikti, yeni_cikti: aynı istek ve model
# çıktısıyla iki sürümden toplanan ara adımlar
for adim in eski_cikti:
    kayit = fark_kaydi(adim, eski_cikti[adim],
                       yeni_cikti[adim])
    if kayit:
        print(json.dumps(kayit))
